def resolve(path, cwd, links):
    # Normalize the starting path
    if path.startswith('/'):
        current = ''
    else:
        current = cwd.lstrip('/')

    # Split path into components
    components = path.split('/')

    # Track number of links followed
    link_count = 0

    # Process each component
    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = ''
            else:
                parts = current.split('/')
                if len(parts) > 1:
                    current = '/'.join(parts[:-1])
                else:
                    current = ''
            continue

        # Append the component
        if current == '':
            current = component
        else:
            current = current + '/' + component

        # Check if this path is a symlink
        canonical_path = '/' + current if current else '/'

        if canonical_path in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the link target
            target = links[canonical_path]

            # Get remaining components
            remaining = components[i:]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                components = target.split('/') + remaining
                current = ''
                i = 0
            else:
                # Relative target - relative to the directory containing the link
                if current == '':
                    link_dir = ''
                else:
                    parts = current.split('/')
                    link_dir = '/'.join(parts[:-1])

                components = link_dir.split('/') + target.split('/') + remaining
                current = ''
                i = 0

    # Return the result
    if current == '':
        return '/'
    else:
        return '/' + current

